package org.springframework.samples.petclinic.rest.controller;

import java.util.List;

/**
 * Raised when a request omits or blanks one or more mandatory fields. Carries the names of the offending
 * fields so the API can report them back to the client in the response body's {@code errors} array.
 */
public class RequiredFieldsMissingException extends RuntimeException {

    private final List<String> fields;

    public RequiredFieldsMissingException(List<String> fields) {
        super("Missing or blank required fields: " + fields);
        this.fields = List.copyOf(fields);
    }

    public List<String> getFields() {
        return this.fields;
    }
}

